'use strict';
let editingRecipe=null;
function foodExtras(next){next.recipes??=[];next.plans??=[];return next}
function ingredientRow(item={name:'',quantity:'',unit:'г'}){return `<div class="ingredient-row"><label>Продукт<input data-ingredient="name" maxlength="80" required value="${esc(item.name)}" placeholder="Рис"></label><label>Количество<input data-ingredient="quantity" type="number" min="0.01" max="1000000" step="any" required value="${esc(item.quantity)}"></label><label>Единица<select data-ingredient="unit">${['г','мл','шт'].map(u=>`<option ${u===item.unit?'selected':''}>${u}</option>`).join('')}</select></label><button type="button" data-remove-ingredient aria-label="Убрать ингредиент">×</button></div>`}
function renderPlanner(){
 foodExtras(state);
 const first=FoodPlan.useFirst(state.stocks,today()),expired=state.stocks.filter(s=>s.quantity>0&&s.expiry&&s.expiry<today());
 $('#use-first').innerHTML=(expired.length?`<div class="expiry-warning"><h3>Срок годности прошёл</h3><p>${expired.map(s=>esc(s.name)).join(', ')}. Эти запасы не учитываются в покупках для меню.</p></div>`:'')+(first.length?`<div class="use-first"><p class="eyebrow">Использовать первым</p>${first.map(s=>`<div><strong>${esc(s.name)}</strong><span>${s.expiry===today()?'Годен до сегодня':`До ${dateText(s.expiry)}`} · ${number(s.quantity)} ${esc(s.unit)}</span></div>`).join('')}</div>`:'');
 const recipes=state.recipes;
 $('#favorites').innerHTML=recipes.length?recipes.map(r=>`<article class="favorite-row"><div><h3>${esc(r.name)}</h3><p>${esc(r.kind)}${r.ingredients.length?` · ${r.ingredients.length} ${plural(r.ingredients.length,['ингредиент','ингредиента','ингредиентов'])}`:''}</p></div><div class="favorite-actions"><button data-repeat-recipe="${esc(r.id)}">Записать</button><button data-edit-recipe="${esc(r.id)}" aria-label="Изменить блюдо ${esc(r.name)}">✎</button></div></article>`).join(''):'<p class="caption">Сохрани любимый завтрак: в следующий раз хватит одного нажатия.</p>';
 const start=FoodPlan.monday($('#week-date').value||today());$('#week-date').value=start;
 $('#week-label').textContent=`${dateText(start)} — ${dateText(plusDays(start,6))}`;
 $('#week-menu').innerHTML=Array.from({length:7},(_,i)=>{const day=plusDays(start,i),plans=state.plans.filter(p=>p.date===day);return `<section class="menu-day"><header><h3>${dateValue(day).toLocaleDateString('ru',{weekday:'short',day:'numeric'})}</h3><button data-plan-day="${day}" aria-label="Добавить блюдо на ${dateText(day)}">＋</button></header>${plans.length?plans.map(p=>{const r=recipes.find(r=>r.id===p.recipeId);return `<div class="menu-entry"><div><strong>${esc(r?.name||'Блюдо удалено')}</strong><p>${esc(r?.kind||'')} · ${number(p.servings)} ${plural(p.servings,['порция','порции','порций'])}</p></div><button data-remove-plan="${esc(p.id)}" aria-label="Убрать из меню ${esc(r?.name||'блюдо')}">×</button></div>`}).join(''):'<p class="caption">Пока свободно</p>'}</section>`}).join('');
 const rows=FoodPlan.shopping(state.plans,recipes,state.stocks,start,today()),missing=rows.filter(r=>r.missing>0);
 $('#menu-shopping-title').textContent=`Для меню · ${dateText(start)} — ${dateText(plusDays(start,6))}`;
 $('#menu-shopping').innerHTML=rows.length?`<p class="caption">Текущий запас вычтен один раз. Учитываются сегодня и будущие дни выбранной недели; продукты, чей срок истечёт к дате блюда, исключены.</p>${missing.length?missing.map(r=>`<article class="buy-ingredient"><div><h3>${esc(r.name)}</h3><p>Нужно ${number(r.needed)} ${esc(r.unit)} · есть ${number(r.available)} ${esc(r.unit)}</p></div><strong>${number(r.missing)} ${esc(r.unit)}</strong></article>`).join(''):'<div class="empty"><h3>Всё для меню уже есть</h3><p>По записанным ингредиентам и текущему остатку.</p></div>'}`:'<p class="caption">Добавь блюда с ингредиентами в меню — здесь появится, чего не хватает.</p>';
 const incomplete=state.plans.filter(p=>p.date>=start&&p.date<=plusDays(start,6)&&p.date>=today()).some(p=>!recipes.find(r=>r.id===p.recipeId)?.ingredients.length);
 if(incomplete)$('#menu-shopping').insertAdjacentHTML('beforeend','<p class="expiry">У некоторых блюд нет ингредиентов. Добавь их в любимых блюдах, чтобы список покупок был полным.</p>');
}
function recipeEditor(id,meal){editingRecipe=id||null;const r=state.recipes.find(r=>r.id===id)||meal||{},f=$('#recipe-form');f.reset();f.elements.name.value=r.name||'';f.elements.kind.value=r.kind||'Завтрак';f.elements.note.value=r.note||'';f.elements.kcal.value=r.kcal??'';$('#ingredients').innerHTML=(r.ingredients||[]).map(ingredientRow).join('');$('#recipe-error').textContent='';$('#recipe-delete').hidden=!id;$('#recipe-editor').showModal()}
$('#recipe-add').onclick=()=>recipeEditor();
$('#ingredient-add').onclick=()=>$('#ingredients').insertAdjacentHTML('beforeend',ingredientRow());
$('#ingredients').onclick=e=>{if(e.target.closest('[data-remove-ingredient]'))e.target.closest('.ingredient-row').remove()};
$('#recipe-form').onsubmit=e=>{e.preventDefault();const v=e.currentTarget.elements,name=v.name.value.trim();if(!name){$('#recipe-error').textContent='Напиши название блюда.';return}const ingredients=[...$('#ingredients').querySelectorAll('.ingredient-row')].map(row=>({name:row.querySelector('[data-ingredient=name]').value.trim(),quantity:Number(row.querySelector('[data-ingredient=quantity]').value),unit:row.querySelector('[data-ingredient=unit]').value}));if(ingredients.some(i=>!i.name||!Number.isFinite(i.quantity)||i.quantity<=0)){ $('#recipe-error').textContent='Укажи продукт и количество для каждого ингредиента.';return}const next=structuredClone(state),r={id:editingRecipe||crypto.randomUUID(),name,kind:v.kind.value,note:v.note.value.trim(),kcal:v.kcal.value===''?null:Number(v.kcal.value),ingredients};if(editingRecipe)next.recipes[next.recipes.findIndex(r=>r.id===editingRecipe)]=r;else next.recipes.push(r);if(persist(next)){$('#recipe-editor').close();toast('Блюдо сохранено в любимых.')}};
$('#recipe-delete').onclick=()=>{if(state.plans.some(p=>p.recipeId===editingRecipe)){$('#recipe-error').textContent='Сначала убери это блюдо из меню — оно там ещё запланировано.';return}const next=structuredClone(state);next.recipes=next.recipes.filter(r=>r.id!==editingRecipe);if(persist(next))$('#recipe-editor').close()};
$('#favorites').onclick=e=>{const b=e.target.closest('button');if(b?.dataset.editRecipe)recipeEditor(b.dataset.editRecipe);if(b?.dataset.repeatRecipe){const r=state.recipes.find(r=>r.id===b.dataset.repeatRecipe),next=structuredClone(state);next.meals.push({id:crypto.randomUUID(),name:r.name,kind:r.kind,note:r.note,kcal:r.kcal,date:$('#diary-date').value||today(),time:new Date().toTimeString().slice(0,5),consumed:null});if(persist(next))toast('Блюдо записано в выбранный день. Запасы не списаны.')}};
$('#meals').addEventListener('click',e=>{const id=e.target.closest('[data-favorite-meal]')?.dataset.favoriteMeal;if(id)recipeEditor(null,state.meals.find(m=>m.id===id))});
function planEditor(day){if(!state.recipes.length){toast('Сначала добавь любимое блюдо и его ингредиенты.');recipeEditor();return}const f=$('#plan-form');f.reset();f.elements.date.value=day;f.elements.recipe.innerHTML=state.recipes.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');$('#plan-editor').showModal()}
$('#week-menu').onclick=e=>{const b=e.target.closest('button');if(b?.dataset.planDay)planEditor(b.dataset.planDay);if(b?.dataset.removePlan){const next=structuredClone(state);next.plans=next.plans.filter(p=>p.id!==b.dataset.removePlan);persist(next)}};
$('#plan-form').onsubmit=e=>{e.preventDefault();const v=e.currentTarget.elements,next=structuredClone(state);next.plans.push({id:crypto.randomUUID(),date:v.date.value,recipeId:v.recipe.value,servings:Number(v.servings.value)});if(persist(next)){$('#week-date').value=FoodPlan.monday(v.date.value);renderPlanner();$('#plan-editor').close();toast('Блюдо добавлено в меню.')}};
$('#week-date').value=FoodPlan.monday(today());$('#week-date').onchange=renderPlanner;
$('#week-prev').onclick=()=>{$('#week-date').value=plusDays($('#week-date').value,-7);renderPlanner()};
$('#week-next').onclick=()=>{$('#week-date').value=plusDays($('#week-date').value,7);renderPlanner()};
document.querySelectorAll('[data-close-extra]').forEach(b=>b.onclick=()=>$('#'+b.dataset.closeExtra).close());
function demoMenu(d){return {recipes:[{id:'demo-omelet',name:'Омлет с помидорами',kind:'Завтрак',note:'Любимый завтрак',kcal:null,ingredients:[{name:'Яйца',quantity:2,unit:'шт'},{name:'Помидоры',quantity:150,unit:'г'}]},{id:'demo-bowl',name:'Мясо с рисом',kind:'Обед',note:'С зеленью',kcal:null,ingredients:[{name:'Мясо',quantity:300,unit:'г'},{name:'Рис',quantity:100,unit:'г'}]}],plans:[{id:'demo-plan-a',date:d,recipeId:'demo-omelet',servings:1},{id:'demo-plan-b',date:d,recipeId:'demo-bowl',servings:2}]}}
if(ready)renderPlanner();
